import sys
from collections import deque

def bfs(n, m, edges, s):
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    distance = [-1] * (n + 1)
    distance[s] = 0
    q = deque([s])

    while q:
        current = q.popleft()
        for neighbor in adj[current]:
            if distance[neighbor] == -1:
                distance[neighbor] = distance[current] + 1
                q.append(neighbor)

    result = []
    for i in range(1, n + 1):
        if i == s:
            continue
        if distance[i] == -1:
            result.append(-1)
        else:
            result.append(6 * distance[i])
    return result

